/** Figures consolidated over a sheet and its descendants. */
interface SheetFigures {
  /** Each person counted once: people whose names or aliases match, as names are compared, are one person. */
  people: number;
  /** In cents: every person's due-total over the tree, trimmed once over them all. */
  due: number;
  /** In cents: every person's overdue-total over the tree, trimmed once over them all. */
  overdue: number;
  /** Per grade, in grade order, the due-totals of the people on it (retired people left out) added up, in cents. */
  grades: { grade: string; due: number }[];
  /** Per status, in status order, how many claims have it. */
  statuses: { status: string; count: number }[];
}

/** How many people there are, those whose names or aliases match (as names are compared) taken as one. */
function distinctPeople(people: Person[]): number {
  const parent = people.map((_, i) => i);
  const root = (i: number): number => (parent[i] === i ? i : (parent[i] = root(parent[i])));
  const byKey = new Map<string, number>();
  people.forEach((p, i) => {
    for (const n of [p.name, ...(p.aliases ?? [])]) {
      const key = nameKey(n);
      const seen = byKey.get(key);
      if (seen === undefined) byKey.set(key, i);
      else parent[root(i)] = root(seen);
    }
  });
  return new Set(people.map((_, i) => root(i))).size;
}

/** The figures over all the people of a tree of sheets. */
function figuresOf(people: Person[]): SheetFigures {
  return {
    people: distinctPeople(people),
    due: dueTotalOf(people),
    overdue: overdueTotalOf(people),
    grades: gradeDueCents(people),
    statuses: statusCounts(people),
  };
}

function csvField(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}
  });
  /** Everyone's overdue-total added up, trimmed (see {@link trimmedSum}). */
  protected readonly overdueTotal = computed(() => (overdueTotalOf(this.people()) / 100).toFixed(2));
  /**
   * The people of each of the sheet's descendants (its children, theirs, and so on), as each shows them: as of the
   * date the sheet is shown as of, while one is set.
   */
  private readonly descendants = signal<Person[][]>([]);
  /**
   * The people counted, the due- and overdue-totals, the due-totals per grade and the claims per status added up, over the sheet and all its descendants, as
   * they stand live; while the sheet is shown as of a date, each as it stood at the end of that day, that date
   * as its today.
   */
  protected readonly consolidated = computed(() => {
    const f = figuresOf([...this.people(), ...this.descendants().flat()]);
    return {
      people: f.people,
      due: (f.due / 100).toFixed(2),
      overdue: (f.overdue / 100).toFixed(2),
      grades: f.grades.map(({ grade, due }) => ({ grade, due: (due / 100).toFixed(2) })),
      statuses: f.statuses,
    };
  });

  constructor() {
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.people.set([]);
      this.role.set(null);
      this.addedHere.set(new Set());
      this.descendants.set([]);
      this.watched.set(new Set());
      this.personError.set(null);
      this.patronError.set(null);
      this.selectedClaims.set(new Set());
  }

  /**
   * The people of each of the sheet's descendants, each read as they stand live, or while the
   * screen shows the sheet as of a date, as they stood at the end of that day (the request names the date).
   */
  private async descendantPeople(sheet: string): Promise<Person[][]> {
    const ids = await firstValueFrom(this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/descendants`));
    return Promise.all(
      ids.map((id) => firstValueFrom(this.http.get<Person[]>(`/api/sheets/${encodeURIComponent(id)}/people`))),
    );
  }
}
